    private void validateStatusTransition(Xbj14Status currentStatus, Xbj14Status newStatus) {

        if (currentStatus == newStatus) {
            return;
        }


        switch (currentStatus) {
            case IN_STORAGE:

                break;
            case ASSOCIATED_WITH_ORDER:
                if (newStatus == Xbj14Status.IN_STORAGE) {
                    throw new Xfw62Exception(
                            "주문과 연결된 상태(ASSOCIATED_WITH_ORDER)에서 보관 상태(IN_STORAGE)로 직접 전환할 수 없습니다.");
                }
                break;
            case ON_AUCTION:
                if (newStatus != Xbj14Status.IN_STORAGE && newStatus != Xbj14Status.SOLD) {
                    throw new Xfw62Exception(
                            "경매 중인 상태(ON_AUCTION)에서는 보관 상태(IN_STORAGE) 또는 판매됨(SOLD) 상태로만 전환할 수 있습니다.");
                }
                break;
            case SOLD:
                throw new Xfw62Exception("판매된 상태(SOLD)에서는 다른 상태로 전환할 수 없습니다.");
